`timescale 1ns/1ps
//------------------------------------------------------------------------------
// Self-checking testbench for ecdsa_secp256k1_sign
//   vectors.mem holds 5 x 256-bit words per vector: d, k, z, r_expected, s_expected
//   (generated by gen_ucode.py from an independent reference implementation)
//
// Run:  iverilog -g2005 -o sim tb_ecdsa_sign.v ecdsa_secp256k1_sign.v \
//                modmul_serial.v ecdsa_ucode_rom.v && vvp sim +NVEC=3
//------------------------------------------------------------------------------
module tb_ecdsa_sign;
    reg          clk = 0;
    reg          rst_n = 0;
    reg          start = 0, mode_pub = 0;
    reg  [255:0] d_in = 0, k_in = 0, z_in = 0;
    wire         busy, done, fail;
    wire [255:0] r_out, s_out, px_out, py_out;

    ecdsa_secp256k1_sign #(.LOW_S(1)) dut (
        .clk(clk), .rst_n(rst_n), .wipe(1'b0), .start(start), .mode_pub(mode_pub),
        .d_in(d_in), .k_in(k_in), .z_in(z_in),
        .busy(busy), .done(done), .fail(fail),
        .r_out(r_out), .s_out(s_out), .px_out(px_out), .py_out(py_out)
    );

    // public-key mode: k_in must equal d_in
    task run_pub(input [255:0] d, input [255:0] ex, input [255:0] ey);
        begin
            @(posedge clk);
            d_in <= d; k_in <= d; z_in <= 0; mode_pub <= 1'b1; start <= 1'b1;
            @(posedge clk);
            start <= 1'b0;
            cycles = 0;
            while (!done && cycles < 4000000) begin @(posedge clk); cycles = cycles + 1; end
            mode_pub <= 1'b0;
            if (!done || fail || px_out !== ex || py_out !== ey) begin
                errors = errors + 1;
                $display("FAIL pubkey d=%h\n  x got %h\n  x exp %h\n  y got %h\n  y exp %h", d, px_out, ex, py_out, ey);
            end else $display("PASS pubkey d=%h...  (%0d cycles)", d[63:0], cycles);
        end
    endtask

    always #5 clk = ~clk;

    localparam NVEC_MAX = 7;                   // vectors in vectors.mem
    reg [255:0] vec [0:NVEC_MAX*5-1];
    integer nvec, v, errors, cycles;
    reg [255:0] n_const;

    task run_one;
        input [255:0] d, k, z;
        begin
            @(posedge clk);
            d_in <= d; k_in <= k; z_in <= z; start <= 1'b1;
            @(posedge clk);
            start <= 1'b0;
            cycles = 0;
            while (!done && cycles < 4000000) begin
                @(posedge clk);
                cycles = cycles + 1;
            end
            if (!done) begin
                $display("TIMEOUT");
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        errors = 0;
        n_const = 256'hFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;
        if (!$value$plusargs("NVEC=%d", nvec)) nvec = 2;
        if (nvec > NVEC_MAX) nvec = NVEC_MAX;
        $readmemh("vectors.mem", vec);

        repeat (4) @(posedge clk);
        rst_n <= 1'b1;
        repeat (2) @(posedge clk);

        // ---- range-check rejection paths (fast) ----
        run_one(256'd1, 256'd0, 256'd5);
        if (fail !== 1'b1) begin $display("FAIL: k=0 not rejected"); errors = errors + 1; end
        else $display("PASS: k = 0 rejected");
        run_one(256'd1, n_const, 256'd5);
        if (fail !== 1'b1) begin $display("FAIL: k=n not rejected"); errors = errors + 1; end
        else $display("PASS: k = n rejected");
        run_one(256'd0, 256'd7, 256'd5);
        if (fail !== 1'b1) begin $display("FAIL: d=0 not rejected"); errors = errors + 1; end
        else $display("PASS: d = 0 rejected");

        // ---- full signatures ----
        for (v = 0; v < nvec; v = v + 1) begin
            run_one(vec[v*5+0], vec[v*5+1], vec[v*5+2]);
            if (fail || r_out !== vec[v*5+3] || s_out !== vec[v*5+4]) begin
                $display("FAIL vec %0d: fail=%b", v, fail);
                $display("  r got %h", r_out);
                $display("  r exp %h", vec[v*5+3]);
                $display("  s got %h", s_out);
                $display("  s exp %h", vec[v*5+4]);
                errors = errors + 1;
            end else begin
                $display("PASS vec %0d  (%0d cycles)  r=%h", v, cycles, r_out);
            end
        end

        // ---- public key mode ----
        `include "tb_core_pub.vh"

        if (errors == 0) $display("ALL TESTS PASSED");
        else             $display("%0d TEST(S) FAILED", errors);
        $finish;
    end
endmodule
